<?php $pageTitle='Configuración'; require __DIR__.'/_header.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);foreach(['whatsapp','pickup_address','business_lat','business_lng','demo_mode'] as $k)set_setting($k,trim($_POST[$k]??''));if(!empty($_FILES['qr']['name'])){$path=upload_file($_FILES['qr'],'qr',['jpg','jpeg','png','webp']);set_setting('qr_image','storage/uploads/'.$path);}$msg='Configuración guardada.';}?><section class="admin-card settings-card"><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>WhatsApp del negocio<input name="whatsapp" value="<?=h(setting('whatsapp','59170000000'))?>"></label><label>Dirección de retiro<input name="pickup_address" value="<?=h(setting('pickup_address',''))?>"></label><div class="field-row"><label>Latitud<input name="business_lat" value="<?=h(setting('business_lat',''))?>"></label><label>Longitud<input name="business_lng" value="<?=h(setting('business_lng',''))?>"></label></div><label>QR de cobro<input type="file" name="qr" accept="image/jpeg,image/png,image/webp"></label><label>Modo demo<select name="demo_mode"><option value="1" <?=setting('demo_mode','1')==='1'?'selected':''?>>Activo</option><option value="0" <?=setting('demo_mode','1')==='0'?'selected':''?>>Desactivado</option></select></label><button class="btn primary">Guardar configuración</button></form></section><?php require __DIR__.'/_footer.php';?>